package com.codepilot1c.core.edt.development;
import org.junit.*;import org.junit.rules.TemporaryFolder;import static org.junit.Assert.*;import java.util.*;import java.nio.file.*;import java.util.concurrent.*;
public class UiRunServiceTest {
 @Rule public TemporaryFolder tmp=new TemporaryFolder();static final String UUID_="11111111-1111-4111-8111-111111111111";
 class Fake implements UiRunService.Backend {
  int clientLookups,prepares,reuses,submits,cleans,captures;boolean reuseFails,closeFails,initialFailure,transportFailure;boolean missingReceipt,collectionFailed,prepUnknown,ready=true,passed=true,unknown,submitThrows,cleanupFails,initialMismatch;String plan="a";CountDownLatch entered=new CountDownLatch(1),gate=new CountDownLatch(0);String prep;Map<String,Object> initialTiming;
  public Map<String,Object> prepare(Map<String,Object>a,String key)throws Exception{prepares++;entered.countDown();gate.await(3,TimeUnit.SECONDS);prep="prep-"+TaskSessionService.fingerprint(List.of(a.get("project"),key));return Map.of("preparation_id",prep,"ready",ready,"state",prepUnknown?"outcome_unknown":ready?"ready":"needs_update");}
  public Map<String,Object> reuse(Map<String,Object>a,String p)throws Exception{reuses++;entered.countDown();gate.await(3,TimeUnit.SECONDS);if(reuseFails)throw new IllegalStateException("channel gone");return Map.of("preparation_id",p,"ready",true);}
  public Map<String,Object> client(String p){clientLookups++;if(!ready)throw new IllegalStateException("No client was reserved");return Map.of("client_id","client","startup_timeline",Map.of("elapsed_ms",12000,"slow_start",true));}
  public String openSession(String p,String c,String r){return "task-"+java.util.UUID.nameUUIDFromBytes((p+"\0"+r).getBytes(java.nio.charset.StandardCharsets.UTF_8));}
  public Map<String,Object> observe(String s,String c,Map<String,Object> timing){initialTiming=timing;if(initialFailure)return Map.of("success",false,"state","transport_failed","transport_state","broken","execution_state","not_dispatched","diagnostics",Map.of("failure_kind","wire_timeout","worker_alive",true));return Map.of("success",true,"snapshot_id","snapshot","window",Map.of("title",initialMismatch?"Other":"Fixture"));}
  public Map<String,Object> submit(String s,String c,Map<String,Object>a){submits++;if(submitThrows)throw new IllegalStateException("unknown");return Map.of("operation_id","op");}
  public Map<String,Object> collect(String s,String c,Map<String,Object>a){var result=new LinkedHashMap<String,Object>(Map.of("success",passed,"postcondition_verified",passed,"outcome_unknown",unknown,"results",List.of(Map.of("success",passed,"postcondition_verified",passed,"step_index",0,"values",Map.of("Name","saved value")))));if(transportFailure){result.put("transport_state","broken");result.put("diagnostics",Map.of("failure_kind","wire_timeout"));result.put("reason","TimeoutError");result.put("payload_truncated",true);result.put("execution_success",false);result.put("mutation_blocked",false);result.put("original_state","result_too_large");}if(collectionFailed)result.put("task_collection_verified",false);return result;}
  public List<Map<String,Object>> capture(String c){captures++;return List.of(Map.of("image_path","owned.png","blank",false));}
  public Map<String,Object> cleanupPlan(String p){if(missingReceipt)throw new IllegalStateException("missing original receipt");return Map.of("plan_sha256",plan,"resources",List.of("owned-client"));}
  public Map<String,Object> cleanup(String p,String expected){assertEquals(plan,expected);cleans++;if(cleanupFails)throw new IllegalStateException("changed");return Map.of("cleaned",true,"business_data_removed",false);}
  public boolean closeSession(String s,String c){if(closeFails)throw new IllegalStateException("uncollected session");return true;}
 }
 Path root;Fake fake;UiRunService service;
 @Before public void init()throws Exception{root=tmp.newFolder().toPath();fake=new Fake();service=new UiRunService(root,fake);}
 Map<String,Object> args(){return new LinkedHashMap<>(Map.of("project","P","base_uuid",UUID_,"idempotency_key","one","steps",List.of(Map.of("action","wait","expected_window","Fixture","expect",Map.of("window","Fixture")))));}
 Map<String,Object> done(String id)throws Exception{for(int i=0;i<500;i++){var s=service.status(id);if(Boolean.TRUE.equals(s.get("terminal")))return s;Thread.sleep(10);}throw new AssertionError("UI run did not finish");}
 Map<String,Object> run(Map<String,Object>a)throws Exception{return done((String)service.start(a).get("ui_run_id"));}
 @Test public void oneRunPreparesExecutesVerifiesAndCleansOwnClient()throws Exception{var r=run(args());assertEquals("completed",r.get("state"));assertEquals(true,r.get("test_passed"));assertEquals(true,r.get("cleanup_verified"));assertEquals(1,fake.submits);assertEquals(1,fake.cleans);assertEquals(0,fake.captures);assertFalse(r.containsKey("details"));assertEquals("edt_ui_run",TaskSessionService.object(r.get("summary")).get("details_tool"));assertTrue(service.details((String)r.get("ui_run_id")).containsKey("details"));}
 @Test public void sameKeyReturnsHistoricalResultWithoutReplaying()throws Exception{var a=args();var first=run(a);var again=service.start(a);assertEquals(first.get("ui_run_id"),again.get("ui_run_id"));assertEquals(1,fake.submits);assertEquals(true,again.get("historical_result"));}
 @Test public void changedArgumentsCannotReuseTheKey()throws Exception{run(args());var a=args();a.put("capture","final");assertThrows(IllegalStateException.class,()->service.start(a));assertEquals(1,fake.submits);}
 @Test public void invalidLaterStepBlocksBeforeAnyPreparation()throws Exception{var a=args();a.put("steps",List.of(Map.of("action","wait","expected_window","Fixture"),Map.of("action","command","expected_window","Fixture","element","Save")));assertThrows(IllegalArgumentException.class,()->service.start(a));assertEquals(0,fake.prepares);}
 @Test public void blockedPreparationNeverSendsActions()throws Exception{fake.ready=false;var r=run(args());assertEquals("blocked",r.get("state"));assertEquals(false,r.get("test_passed"));assertEquals(0,fake.submits);assertEquals(1,fake.cleans);}
 @Test public void changedInitialWindowBlocksBeforeSubmit()throws Exception{fake.initialMismatch=true;var r=run(args());assertEquals("failed",r.get("state"));assertEquals(0,fake.submits);assertEquals(1,fake.captures);assertEquals(true,r.get("cleanup_verified"));}
 @Test public void failedPostconditionDoesNotBecomeAJobSuccess()throws Exception{fake.passed=false;var r=run(args());assertEquals(false,r.get("test_passed"));assertEquals("failed",r.get("state"));assertEquals(1,fake.submits);assertEquals(1,fake.captures);assertEquals(true,r.get("cleanup_verified"));}
 @Test public void unknownOutcomeCannotBeBypassedByNewKeyEvenAfterCleanup()throws Exception{fake.unknown=true;fake.passed=false;var r=run(args());assertEquals("outcome_unknown",r.get("state"));assertEquals(true,r.get("cleanup_verified"));var a=args();a.put("idempotency_key","new");assertThrows(IllegalStateException.class,()->service.start(a));assertEquals(1,fake.submits);}
 @Test public void lostSubmissionReceiptIsNeverReplayed()throws Exception{fake.submitThrows=true;var r=run(args());assertEquals(true,r.get("outcome_unknown"));service.start(args());assertEquals(1,fake.submits);}
 @Test public void optionalFinalCaptureAndFullDetailsSurviveCleanup()throws Exception{var a=args();a.put("capture","final");var r=run(a);assertEquals(1,fake.captures);assertEquals(1,((List<?>)r.get("artifacts")).size());assertEquals("saved value",((Map<?,?>)((Map<?,?>)((List<?>)((Map<?,?>)service.details((String)r.get("ui_run_id")).get("details")).get("results")).get(0)).get("values")).get("Name"));}
 @Test public void manualCleanupUsesActualPreparationInventoryAndStaleHashBlocks()throws Exception{var a=args();a.put("auto_cleanup",false);var r=run(a);String id=(String)r.get("ui_run_id");assertEquals(0,fake.cleans);var plan=service.cleanupPreview(id);String stale=(String)plan.get("plan_sha256");fake.plan="changed";assertThrows(IllegalStateException.class,()->service.cleanup(id,stale));assertEquals(0,fake.cleans);plan=service.cleanupPreview(id);assertEquals(true,service.cleanup(id,(String)plan.get("plan_sha256")).get("cleanup_verified"));}
 @Test public void cleanupFailureIsReportedAndCanBeRetriedWithoutActions()throws Exception{fake.cleanupFails=true;var r=run(args());assertEquals(true,r.get("test_passed"));assertEquals(false,r.get("cleanup_verified"));fake.cleanupFails=false;String id=(String)r.get("ui_run_id");var p=service.cleanupPreview(id);service.cleanup(id,(String)p.get("plan_sha256"));assertEquals(1,fake.submits);}
 @Test public void concurrentSameKeyCannotLaunchTwice()throws Exception{fake.gate=new CountDownLatch(1);String id=(String)service.start(args()).get("ui_run_id");assertTrue(fake.entered.await(3,TimeUnit.SECONDS));assertEquals(id,service.start(args()).get("ui_run_id"));assertThrows(IllegalStateException.class,()->service.cleanupPreview(id));fake.gate.countDown();done(id);assertEquals(1,fake.prepares);}
 @Test public void restartReceiptNeverStartsBackend()throws Exception{String id="ui-"+"a".repeat(64);Files.writeString(root.resolve(id+".json"),new com.google.gson.Gson().toJson(Map.of("ui_run_id",id,"terminal",false,"state","dispatching")));assertEquals("outcome_unknown",service.status(id).get("state"));assertEquals(0,fake.prepares);}
 @Test public void arbitraryEndpointOrImplicitDatabaseUpdateAreRejected()throws Exception{for(String field:List.of("endpoint","update_db","native_path","client_id")){var a=args();a.put(field,"unsafe");assertThrows(IllegalArgumentException.class,()->service.start(a));}assertEquals(0,fake.prepares);}
 @Test public void unknownStartupRemainsUnknownEvenAfterOwnedCleanup()throws Exception{fake.ready=false;fake.prepUnknown=true;var r=run(args());assertEquals("outcome_unknown",r.get("state"));assertEquals(true,r.get("outcome_unknown"));assertEquals(true,r.get("cleanup_verified"));var a=args();a.put("idempotency_key","replacement");assertThrows(IllegalStateException.class,()->service.start(a));assertEquals(0,fake.submits);}
 @Test public void slowMapWaitRequiresAndAcceptsAnExplicitRunBudget()throws Exception{var a=args();a.put("steps",List.of(Map.of("action","wait","expected_window","Fixture","wait_timeout_ms",90000)));assertThrows(IllegalArgumentException.class,()->service.start(a));assertEquals(0,fake.prepares);a.put("operation_timeout_s",90);var r=run(a);assertEquals(true,r.get("test_passed"));assertEquals(90,((Number)TaskSessionService.object(service.details((String)r.get("ui_run_id")).get("timing_config")).get("operation_timeout_s")).intValue());assertEquals(90,((Number)fake.initialTiming.get("operation_timeout_s")).intValue());}
 @Test public void missingOriginalPreparationReceiptDoesNotClaimCleanup()throws Exception{fake.missingReceipt=true;var r=run(args());assertEquals(true,r.get("test_passed"));assertEquals(false,r.get("cleanup_verified"));assertEquals(0,fake.cleans);assertThrows(IllegalStateException.class,()->service.cleanupPreview((String)r.get("ui_run_id")));}
 @Test public void collectionFailureRetainsFullResultWithoutPassingTheRun()throws Exception{fake.collectionFailed=true;var r=run(args());assertEquals("failed",r.get("state"));assertEquals(false,r.get("test_passed"));assertEquals(true,r.get("cleanup_verified"));var full=TaskSessionService.object(service.details((String)r.get("ui_run_id")).get("details"));assertEquals(true,full.get("success"));assertEquals(false,full.get("task_collection_verified"));assertTrue(full.containsKey("results"));}
 @Test public void retainedClientReusedWithoutPreparingOrCleaningOwner()throws Exception{var a=args();a.put("auto_cleanup",false);var owner=run(a);String oid=(String)owner.get("ui_run_id");var b=args();b.put("idempotency_key","two");b.put("reuse_from_ui_run_id",oid);var child=run(b);assertEquals(true,child.get("test_passed"));assertEquals(true,child.get("client_reused"));assertEquals(1,fake.prepares);assertEquals(1,fake.reuses);assertEquals(0,fake.cleans);assertEquals(true,child.get("cleanup_verified"));assertEquals("client_retained",TaskSessionService.object(owner.get("diagnostic")).get("code"));var plan=service.cleanupPreview(oid);service.cleanup(oid,(String)plan.get("plan_sha256"));assertEquals(1,fake.cleans);assertEquals(2,fake.submits);}
 @Test public void cleanedOwnerAndWrongUuidCannotBeReused()throws Exception{String id=(String)run(args()).get("ui_run_id");var a=args();a.put("idempotency_key","two");a.put("reuse_from_ui_run_id",id);assertThrows(IllegalStateException.class,()->service.start(a));assertEquals(0,fake.reuses);}
 @Test public void lostReusedClientDoesNotLaunchAReplacement()throws Exception{var a=args();a.put("auto_cleanup",false);String id=(String)run(a).get("ui_run_id");fake.reuseFails=true;var b=args();b.put("idempotency_key","two");b.put("reuse_from_ui_run_id",id);var child=run(b);assertEquals(false,child.get("test_passed"));assertEquals(1,fake.prepares);assertEquals(1,fake.submits);assertEquals(0,fake.cleans);}
 @Test public void unknownBorrowerBlocksFurtherReuseEvenWhenReleased()throws Exception{var a=args();a.put("auto_cleanup",false);String id=(String)run(a).get("ui_run_id");var b=args();b.put("idempotency_key","two");b.put("reuse_from_ui_run_id",id);fake.unknown=true;fake.passed=false;run(b);b.put("idempotency_key","three");assertThrows(IllegalStateException.class,()->service.start(b));assertEquals(1,fake.reuses);}
 @Test public void compactStatusOmitsValuesAndTimelinesButDetailsRetainThem()throws Exception{var r=run(args());String text=new com.google.gson.Gson().toJson(r);assertFalse(text.contains("saved value"));assertFalse(r.containsKey("startup"));assertFalse(r.containsKey("phase_timings_ms"));assertTrue(service.details((String)r.get("ui_run_id")).containsKey("startup"));assertTrue(r.containsKey("details_call"));assertEquals("passed",TaskSessionService.object(r.get("diagnostic")).get("code"));}
 @Test public void activeBorrowerBlocksOwnerCleanupAndAnotherBatch()throws Exception{var a=args();a.put("auto_cleanup",false);String id=(String)run(a).get("ui_run_id");fake.gate=new CountDownLatch(1);fake.entered=new CountDownLatch(1);var b=args();b.put("idempotency_key","two");b.put("reuse_from_ui_run_id",id);String child=(String)service.start(b).get("ui_run_id");assertTrue(fake.entered.await(2,TimeUnit.SECONDS));assertThrows(IllegalStateException.class,()->service.cleanupPreview(id));b.put("idempotency_key","three");assertThrows(IllegalStateException.class,()->service.start(b));fake.gate.countDown();done(child);assertEquals(0,fake.cleans);}
 @Test public void retainedOwnerCannotBeReusedWithChangedBaseOrProject()throws Exception{var a=args();a.put("auto_cleanup",false);String id=(String)run(a).get("ui_run_id");for(String field:List.of("project","base_uuid")){var b=args();b.put("idempotency_key","two");b.put("reuse_from_ui_run_id",id);b.put(field,field.equals("project")?"other":"22222222-2222-4222-8222-222222222222");assertThrows(IllegalStateException.class,()->service.start(b));}assertEquals(0,fake.reuses);}
 @Test public void diagnosticNeverSuggestsReplayForUnknownAndIdentifiesFailedStep(){var unknown=UiRunService.diagnose(Map.of("outcome_unknown",true,"terminal",true,"cleanup_verified",true));assertEquals("outcome_unknown",unknown.get("code"));assertEquals(false,unknown.get("executor_switch_allowed"));var failed=UiRunService.diagnose(Map.of("terminal",true,"cleanup_verified",true,"summary",Map.of("failed_step_index",2)));assertEquals("ui_step_not_verified",failed.get("code"));}
 @Test public void failedBorrowerSessionCloseBlocksNewReuseUntilOriginalCleanupSucceeds()throws Exception{var a=args();a.put("auto_cleanup",false);String owner=(String)run(a).get("ui_run_id");fake.closeFails=true;var b=args();b.put("idempotency_key","two");b.put("reuse_from_ui_run_id",owner);var child=run(b);assertEquals(true,child.get("test_passed"));assertEquals(false,child.get("cleanup_verified"));assertEquals(false,child.get("session_closed"));b.put("idempotency_key","three");assertThrows(IllegalStateException.class,()->service.start(b));fake.closeFails=false;String id=(String)child.get("ui_run_id");var p=service.cleanupPreview(id);assertEquals(true,service.cleanup(id,(String)p.get("plan_sha256")).get("cleanup_verified"));assertEquals(2,fake.submits);assertEquals(0,fake.cleans);var ownerPlan=service.cleanupPreview(owner);assertEquals(false,service.cleanup(owner,(String)ownerPlan.get("plan_sha256")).get("client_retained"));}
 @Test public void waitOnSameRunReturnsVerifiedResultWithoutAnotherSubmission()throws Exception{
  fake.gate=new CountDownLatch(1);var started=service.start(args());String id=(String)started.get("ui_run_id");assertTrue(fake.entered.await(2,TimeUnit.SECONDS));
  var first=service.waitFor(id,0);assertEquals(true,first.get("timed_out"));assertEquals(false,first.get("terminal"));fake.gate.countDown();var result=service.waitFor(id,3000);assertEquals(true,result.get("test_passed"));assertEquals(false,result.get("timed_out"));assertEquals(1,fake.submits);assertEquals(1,fake.prepares);
 }
 @Test public void waitingUnknownNeverStartsAnotherClient()throws Exception{fake.unknown=true;fake.passed=false;String id=(String)run(args()).get("ui_run_id");var observed=WorkflowReplies.ui(service.waitFor(id,100));assertEquals(true,observed.get("outcome_unknown"));assertEquals(1,fake.prepares);assertEquals(1,fake.submits);assertEquals("details",TaskSessionService.object(TaskSessionService.object(TaskSessionService.object(observed.get("next_call")).get("arguments")).get("args")).get("action"));}


 @Test public void compactUiFailureRetainsTransportDiagnostics()throws Exception{fake.passed=false;fake.transportFailure=true;var result=run(args());var summary=TaskSessionService.object(result.get("summary"));assertEquals("broken",summary.get("transport_state"));assertEquals("wire_timeout",TaskSessionService.object(summary.get("diagnostics")).get("failure_kind"));assertEquals("TimeoutError",summary.get("reason"));assertEquals(true,summary.get("payload_truncated"));assertEquals(false,summary.get("execution_success"));assertEquals(false,summary.get("mutation_blocked"));assertEquals("result_too_large",summary.get("original_state"));assertFalse(AgentResponses.JSON.toJson(result).contains("saved value"));}
 @Test public void initialObservationFailureIsSavedBeforeAnyMutation()throws Exception{fake.initialFailure=true;var result=run(args());assertEquals(false,result.get("test_passed"));assertEquals(0,fake.submits);var failure=TaskSessionService.object(result.get("initial_observation_failure"));assertEquals("not_dispatched",failure.get("execution_state"));assertEquals("wire_timeout",TaskSessionService.object(failure.get("diagnostics")).get("failure_kind"));}
 @Test public void preConsentPauseHasNoSubmissionOrCleanupAndResumesOriginalBatchOnce()throws Exception {
  var allowed=new java.util.concurrent.atomic.AtomicBoolean();fake=new Fake(){public Map<String,Object> prepare(Map<String,Object>a,String key)throws Exception {var base=new LinkedHashMap<>(super.prepare(a,key));if(!allowed.get()){base.put("ready",false);base.put("state","awaiting_consent");base.put("decision",Map.of("options",List.of()));}return base;}};service=new UiRunService(root,fake);var paused=run(args());String id=(String)paused.get("ui_run_id");assertEquals("awaiting_consent",paused.get("state"));assertEquals(false,paused.get("outcome_unknown"));assertEquals(0,fake.submits);assertEquals(0,fake.cleans);assertFalse(service.details(id).containsKey("client_id"));allowed.set(true);service.resume(id);var done=done(id);assertEquals(true,done.get("test_passed"));assertEquals(1,fake.submits);assertEquals(1,fake.cleans);assertThrows(IllegalStateException.class,()->service.resume(id));
 }
 @Test public void unknownUiRunCannotUseConsentResumeToReplay()throws Exception {fake.unknown=true;fake.passed=false;String id=(String)run(args()).get("ui_run_id");assertThrows(IllegalStateException.class,()->service.resume(id));assertEquals(1,fake.submits);}
 @Test public void preClientBlockPreservesKnownOutcomeWithoutResolvingMissingClient()throws Exception{fake.ready=false;var r=run(args());assertEquals("blocked",r.get("state"));assertEquals(false,r.get("outcome_unknown"));assertEquals("needs_update",r.get("reason"));assertEquals(0,fake.clientLookups);assertEquals(0,fake.submits);}
}
